@isTest
private class OpportunityWonHandlerTest {

    private static final String WON = 'Closed Won';
    private static final String HANDOVER = 'Handover to Customer Success';
    private static final Date CLOSE_DATE = Date.newInstance(2030, 1, 15);

    // ---------- Helpers ----------

    private static Account makeAccount(String rating) {
        Account a = new Account(Name = 'Test Account ' + Math.abs(Crypto.getRandomInteger()));
        if (rating != null) {
            a.Rating = rating;
        }
        insert a;
        return a;
    }

    private static Opportunity makeOpp(Id accountId, String stage) {
        return new Opportunity(
            Name = 'Test Opp ' + Math.abs(Crypto.getRandomInteger()),
            AccountId = accountId,
            StageName = stage,
            CloseDate = CLOSE_DATE
        );
    }

    private static Opportunity queryOpp(Id oppId) {
        return [SELECT Id, Name, StageName, NextStep, CloseDate, AccountId, OwnerId
                FROM Opportunity WHERE Id = :oppId];
    }

    private static Map<Id, Opportunity> queryOpps(Set<Id> oppIds) {
        return new Map<Id, Opportunity>([SELECT Id, Name, StageName, NextStep, CloseDate, AccountId, OwnerId
                FROM Opportunity WHERE Id IN :oppIds]);
    }

    private static List<Task> tasksFor(Set<Id> oppIds) {
        return [SELECT Id, Subject, WhatId, OwnerId, ActivityDate, Priority
                FROM Task WHERE WhatId IN :oppIds];
    }

    private static List<Task> tasksFor(Id oppId) {
        return tasksFor(new Set<Id>{ oppId });
    }

    private static String ratingOf(Id accountId) {
        return [SELECT Rating FROM Account WHERE Id = :accountId].Rating;
    }

    private static User createOtherUser() {
        User other;
        System.runAs(new User(Id = UserInfo.getUserId())) {
            Profile p = [SELECT Id FROM Profile WHERE Name = 'Standard User' LIMIT 1];
            String unique = String.valueOf(Math.abs(Crypto.getRandomInteger())) + '.' +
                            String.valueOf(System.currentTimeMillis());
            other = new User(
                Alias = 'wonhnd',
                Email = 'won.handler.' + unique + '@example.com',
                EmailEncodingKey = 'UTF-8',
                LastName = 'OtherOwner',
                LanguageLocaleKey = 'en_US',
                LocaleSidKey = 'en_US',
                ProfileId = p.Id,
                TimeZoneSidKey = 'GMT',
                UserName = 'won.handler.' + unique + '@example.com.test'
            );
            insert other;
        }
        return other;
    }

    private static void assertHandoverTask(Task t, Opportunity opp, Id expectedOwnerId) {
        System.assertEquals('Customer kick-off', t.Subject, 'Task Subject');
        System.assertEquals(opp.Id, t.WhatId, 'Task WhatId must be the opportunity');
        System.assertEquals(expectedOwnerId, t.OwnerId, 'Task OwnerId must be the opportunity owner');
        System.assertNotEquals(null, opp.CloseDate, 'Opportunity CloseDate must be populated for ActivityDate check');
        // Assert relative to the saved opportunity's CloseDate, not a hard-coded
        // absolute date: this is exactly the documented rule (CloseDate + 7).
        System.assertEquals(opp.CloseDate.addDays(7), t.ActivityDate, 'Task ActivityDate must be CloseDate + 7 days');
        System.assertEquals('High', t.Priority, 'Task Priority');
    }

