@IsTest
private class ContactsTest {
    private static final String EXISTING_LEAD_SOURCE = 'Partner Referral';

    // -------------------------------------------------------------------------
    // Helpers
    // -------------------------------------------------------------------------

    private static void fireInsert(List<Contact> records) {
        fflib_SObjectDomain.Test.Database.onInsert(records);
        fflib_SObjectDomain.triggerHandler(Contacts.class);
    }

    private static void fireUpdate(List<Contact> records, Map<Id, SObject> existingRecords) {
        fflib_SObjectDomain.Test.Database.onUpdate(records, existingRecords);
        fflib_SObjectDomain.triggerHandler(Contacts.class);
    }

    private static List<fflib_SObjectDomain.Error> getDomainErrors() {
        return fflib_SObjectDomain.Test.Database.Errors;
    }

    private static void assertNoDomainErrors() {
        List<fflib_SObjectDomain.Error> errors = getDomainErrors();
        Assert.isTrue(
            errors == null || errors.isEmpty(),
            'Expected no domain errors, but found: ' + errors
        );
    }

    private static void assertSingleFutureBirthdateError(Contact expectedRecord) {
        List<fflib_SObjectDomain.Error> errors = getDomainErrors();
        Assert.isNotNull(errors, 'Expected domain errors to be recorded.');
        Assert.areEqual(1, errors.size(), 'Expected exactly one domain error.');
        Assert.areEqual(
            Contacts.FUTURE_BIRTHDATE,
            errors[0].message,
            'Unexpected error message.'
        );

        // fflib_SObjectDomain.Error does not expose the target record / field
        // as public `record` / `field` members, so verify them via the
        // serialized error, which contains the record and the SObjectField
        // the error was raised against. This fails if the error is moved to
        // a different field, attached to a different record, or the message
        // is changed.
        String serializedError = JSON.serialize(errors[0]);
        Assert.isTrue(
            serializedError.contains('Birthdate'),
            'Error should be on the Birthdate field, but was: ' + serializedError
        );
        Assert.isTrue(
            serializedError.contains(Contacts.FUTURE_BIRTHDATE),
            'Serialized error should contain the expected message, but was: ' + serializedError
        );
        if (expectedRecord != null && String.isNotBlank(expectedRecord.LastName)) {
            Assert.isTrue(
                serializedError.contains(expectedRecord.LastName),
                'Error should be attached to the offending record, but was: ' + serializedError
            );
        }
    }

