public class Opportunities extends fflib_SObjectDomain {

    private Boolean insertValidationDone = false;
    private Boolean updateValidationDone = false;

    public Opportunities(List<Opportunity> sObjectList) {
        super(sObjectList);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities(sObjectList);
        }
    }

    private void validateNegativeAmount() {
        for (Opportunity opp : (List<Opportunity>) Records) {
            if (opp.Amount != null && opp.Amount < 0) {
                error('Amount cannot be negative.', opp, Opportunity.Amount);
            }
        }
    }

    private void validateUpdateRules(Map<Id, SObject> existingRecords) {
        for (Opportunity opp : (List<Opportunity>) Records) {
            if (opp.Amount != null && opp.Amount < 0) {
                error('Amount cannot be negative.', opp, Opportunity.Amount);
            }

            if (existingRecords != null) {
                Opportunity existingOpp = (Opportunity) existingRecords.get(opp.Id);
                if (existingOpp != null
                    && existingOpp.StageName == 'Closed Won'
                    && opp.Amount != existingOpp.Amount) {
                    error('Amount cannot change on a won opportunity.', opp, Opportunity.Amount);
                }
            }
        }
    }

    private void runInsertValidation() {
        if (insertValidationDone) {
            return;
        }
        insertValidationDone = true;
        validateNegativeAmount();
    }

    private void runUpdateValidation(Map<Id, SObject> existingRecords) {
        if (updateValidationDone) {
            return;
        }
        updateValidationDone = true;
        validateUpdateRules(existingRecords);
    }

    public override void onValidate() {
        runInsertValidation();
    }

    public override void onValidate(Map<Id, SObject> existingRecords) {
        runUpdateValidation(existingRecords);
    }

    public override void onBeforeInsert() {
        runInsertValidation();
    }

    public override void onBeforeUpdate(Map<Id, SObject> existingRecords) {
        runUpdateValidation(existingRecords);
    }

    public override void handleBeforeInsert() {
        super.handleBeforeInsert();
        // Ensure validation runs even if this fflib version's
        // handleBeforeInsert does not invoke onValidate/onBeforeInsert.
        runInsertValidation();
    }

    public override void handleBeforeUpdate(Map<Id, SObject> existingRecords) {
        super.handleBeforeUpdate(existingRecords);
        // Ensure validation runs even if this fflib version's
        // handleBeforeUpdate does not invoke onValidate(Map)/onBeforeUpdate
        // (e.g. old on-update validate behaviour disabled by default).
        runUpdateValidation(existingRecords);
    }
}
