public with sharing class AccountOnboardingService {

    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName) {
        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return new List<Account>();
        }

        List<Account> resultAccounts = new List<Account>();

        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new List<Schema.SObjectType>{
                Account.SObjectType,
                Contact.SObjectType
            }
        );

        for (String acctName : contactLastNamesByAccountName.keySet()) {
            Account acctRecord = new Account(Name = acctName);
            resultAccounts.add(acctRecord);
            uow.registerNew(acctRecord);

            List<String> lastNames = contactLastNamesByAccountName.get(acctName);
            if (lastNames == null) {
                continue;
            }

            for (String lastNameValue : lastNames) {
                if (String.isBlank(lastNameValue)) {
                    continue;
                }
                Contact conRecord = new Contact(LastName = lastNameValue);
                uow.registerNew(conRecord, Contact.AccountId, acctRecord);
            }
        }

        uow.commitWork();

        return resultAccounts;
    }
}
