public inherited sharing class OpportunityWinService {
    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities = OpportunitiesSelector.newInstance()
            .selectById(opportunityIds);

        if (opportunities == null || opportunities.isEmpty()) {
            return 0;
        }

        fflib_ISObjectUnitOfWork unitOfWork = Application.UnitOfWork.newInstance();

        Integer closedCount = 0;

        for (Opportunity opportunity : opportunities) {
            if (opportunity.StageName == 'Closed Won') {
                continue;
            }

            opportunity.StageName = 'Closed Won';
            opportunity.CloseDate = Date.today();

            unitOfWork.registerDirty(opportunity);

            // Deal_Won__e has Publish Immediately behaviour, so publishing it
            // via EventBus.publish (or via a publish-on-success registration)
            // inside the transaction would deliver it even if the transaction
            // later rolled back. registerPublishAfterSuccessTransaction defers
            // publication until after the transaction has committed
            // successfully: fflib only publishes these records after
            // commitWork() succeeds and the transaction commits. If the
            // Opportunity DML in commitWork() fails, the exception propagates
            // before any event is published.
            unitOfWork.registerPublishAfterSuccessTransaction(
                new Deal_Won__e(
                    Opportunity_Id__c = String.valueOf(opportunity.Id),
                    Amount__c = opportunity.Amount
                )
            );

            closedCount++;
        }

        // Single commit for all Opportunity updates and the deferred event
        // publication. No try/catch: failures must propagate to the caller
        // and no Deal_Won__e may be published for unsaved Opportunities.
        unitOfWork.commitWork();

        return closedCount;
    }
}
