public with sharing class HouseholdService {

    /**
     * Creates one NPSP Household Account containing all supplied contacts,
     * with the first contact as the household's primary contact.
     *
     * The household is not created directly. Instead, the first contact is
     * inserted on its own, with no AccountId, so that NPSP's Household
     * Account model creates exactly one Household Account for it, applies
     * the HH_Account record type, and generates the household name and
     * greetings. The remaining contacts are then inserted into that same
     * household, so no additional (empty) household accounts are created.
     *
     * @param members New contacts (no Id, no AccountId) for one household.
     * @return Id of the NPSP Household Account containing all members.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty.');
        }

        // Insert the primary contact alone. Under the NPSP Household Account
        // model, NPSP creates one Household Account (HH_Account record type),
        // names it automatically, generates greetings, and makes this contact
        // its primary contact.
        Contact primaryContact = members[0];
        insert primaryContact;

        // The AccountId is assigned by NPSP in a trigger, so it is not
        // reliably populated on the in-memory record; re-query it.
        Id householdId = [
            SELECT AccountId
            FROM Contact
            WHERE Id = :primaryContact.Id
        ].AccountId;

        if (householdId == null) {
            throw new IllegalArgumentException(
                'NPSP did not create a Household Account for the primary contact. ' +
                'Verify that the NPSP Household Account model is enabled.'
            );
        }

        // Join the remaining contacts to the household NPSP already created.
        // Because their AccountId is set, NPSP will not create further
        // household accounts for them, leaving no empty households behind.
        if (members.size() > 1) {
            List<Contact> remainingMembers = new List<Contact>();
            for (Integer i = 1; i < members.size(); i++) {
                members[i].AccountId = householdId;
                remainingMembers.add(members[i]);
            }
            insert remainingMembers;
        }

        // Guarantee the first contact is recorded as the primary contact,
        // without relying solely on NPSP's defaulting behaviour.
        Account household = [
            SELECT Id, npe01__One2OneContact__c
            FROM Account
            WHERE Id = :householdId
        ];
        if (household.npe01__One2OneContact__c != primaryContact.Id) {
            household.npe01__One2OneContact__c = primaryContact.Id;
            update household;
        }

        return householdId;
    }
}
