public class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();

        for (SoftCreditRequest req : requests) {
            if (req == null || req.opportunityId == null || req.contactId == null) {
                throw new SoftCreditException('Each request must specify an opportunity and a contact.');
            }
            opportunityIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        // SOQL 1: Opportunities needed for validation.
        Map<Id, Opportunity> opportunitiesById = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ]);

        // Validate the whole call before any DML (and before further processing).
        for (SoftCreditRequest req : requests) {
            Opportunity opp = opportunitiesById.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + req.opportunityId);
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Partial soft credit amount must be positive.');
            }
            if (opp.Amount == null || req.amount > opp.Amount) {
                throw new SoftCreditException('Partial soft credit amount cannot exceed the opportunity amount.');
            }
            if (req.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException('The primary contact cannot receive a partial soft credit.');
            }
        }

        // SOQL 2: Existing contact roles for the requested pairs.
        List<OpportunityContactRole> existingRoles = [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :opportunityIds
            AND ContactId IN :contactIds
        ];

        Map<String, OpportunityContactRole> roleByPair = new Map<String, OpportunityContactRole>();
        for (OpportunityContactRole ocr : existingRoles) {
            String key = pairKey(ocr.OpportunityId, ocr.ContactId);
            if (!roleByPair.containsKey(key)) {
                roleByPair.put(key, ocr);
            }
        }

        // SOQL 3: Existing partial soft credits for the requested pairs.
        // npsp__Contact_Name__c is not writeable (formula/derived), so it is
        // only read/queried here to find existing records; it is never set.
        // npsp__Contact__c is the writeable contact field.
        List<npsp__Partial_Soft_Credit__c> existingCredits = [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Contact_Name__c,
                   npsp__Amount__c, npsp__Role_Name__c, npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :opportunityIds
            AND (npsp__Contact__c IN :contactIds OR npsp__Contact_Name__c IN :contactIds)
        ];

        Map<String, npsp__Partial_Soft_Credit__c> creditByPair =
            new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : existingCredits) {
            Set<String> contactKeys = new Set<String>();
            String byContact = normalisedIdString(psc.npsp__Contact__c);
            String byContactName = normalisedIdString(psc.npsp__Contact_Name__c);
            if (byContact != null) {
                contactKeys.add(byContact);
            }
            if (byContactName != null) {
                contactKeys.add(byContactName);
            }
            for (String contactKey : contactKeys) {
                String key = String.valueOf(psc.npsp__Opportunity__c) + '|' + contactKey;
                if (!creditByPair.containsKey(key)) {
                    creditByPair.put(key, psc);
                }
            }
        }

        // Prepare OpportunityContactRole inserts / updates.
        List<OpportunityContactRole> rolesToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToUpdate = new List<OpportunityContactRole>();
        Map<String, OpportunityContactRole> roleForRequest = new Map<String, OpportunityContactRole>();

        for (SoftCreditRequest req : requests) {
            String key = pairKey(req.opportunityId, req.contactId);
            OpportunityContactRole ocr = roleByPair.get(key);
            if (ocr == null) {
                ocr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role
                );
                rolesToInsert.add(ocr);
                roleByPair.put(key, ocr);
            } else if (ocr.Role != req.role) {
                ocr.Role = req.role;
                rolesToUpdate.add(ocr);
            }
            roleForRequest.put(key, ocr);
        }

        // DML 1 and 2 (each only executed when needed).
        if (!rolesToInsert.isEmpty()) {
            insert rolesToInsert;
        }
        if (!rolesToUpdate.isEmpty()) {
            update rolesToUpdate;
        }

        // Prepare Partial Soft Credit inserts / updates, now that every
        // contact role has an Id to link via npsp__Contact_Role_ID__c.
        List<npsp__Partial_Soft_Credit__c> creditsToInsert = new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> creditsToUpdate = new List<npsp__Partial_Soft_Credit__c>();
        Set<Id> creditsAlreadyQueuedForUpdate = new Set<Id>();

        for (SoftCreditRequest req : requests) {
            String key = pairKey(req.opportunityId, req.contactId);
            OpportunityContactRole ocr = roleForRequest.get(key);
            npsp__Partial_Soft_Credit__c psc = creditByPair.get(key);

            if (psc == null) {
                psc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId,
                    npsp__Amount__c = req.amount,
                    npsp__Role_Name__c = req.role,
                    npsp__Contact_Role_ID__c = String.valueOf(ocr.Id)
                );
                creditsToInsert.add(psc);
                creditByPair.put(key, psc);
            } else {
                psc.npsp__Opportunity__c = req.opportunityId;
                psc.npsp__Contact__c = req.contactId;
                psc.npsp__Amount__c = req.amount;
                psc.npsp__Role_Name__c = req.role;
                psc.npsp__Contact_Role_ID__c = String.valueOf(ocr.Id);
                if (psc.Id != null && !creditsAlreadyQueuedForUpdate.contains(psc.Id)) {
                    creditsToUpdate.add(psc);
                    creditsAlreadyQueuedForUpdate.add(psc.Id);
                }
            }
        }

        // DML 3 and 4 (each only executed when needed).
        if (!creditsToInsert.isEmpty()) {
            insert creditsToInsert;
        }
        if (!creditsToUpdate.isEmpty()) {
            update creditsToUpdate;
        }
    }

    private static String pairKey(Id opportunityId, Id contactId) {
        return String.valueOf(opportunityId) + '|' + String.valueOf(contactId);
    }

    private static String normalisedIdString(Object value) {
        if (value == null) {
            return null;
        }
        String raw = String.valueOf(value);
        if (raw.length() == 15 || raw.length() == 18) {
            try {
                return String.valueOf(Id.valueOf(raw));
            } catch (Exception e) {
                return raw;
            }
        }
        return raw;
    }
}
