global with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;
    private static final String CLOSED_WON_STAGE = 'Closed Won';

    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newList,
        List<SObject> oldList,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        if (
            triggerAction != npsp.TDTM_Runnable.Action.AfterInsert &&
            triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate
        ) {
            return dmlWrapper;
        }

        if (newList == null || newList.isEmpty()) {
            return dmlWrapper;
        }

        Map<Id, Opportunity> oldOpportunitiesById = new Map<Id, Opportunity>();
        if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate && oldList != null) {
            for (SObject oldRecord : oldList) {
                Opportunity oldOpportunity = (Opportunity) oldRecord;
                oldOpportunitiesById.put(oldOpportunity.Id, oldOpportunity);
            }
        }

        List<Task> tasksToInsert = new List<Task>();

        for (SObject newRecord : newList) {
            Opportunity opportunity = (Opportunity) newRecord;

            if (!isMajorClosedWon(opportunity)) {
                continue;
            }

            if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate) {
                Opportunity oldOpportunity = oldOpportunitiesById.get(opportunity.Id);
                if (oldOpportunity != null && isMajorClosedWon(oldOpportunity)) {
                    continue;
                }
            }

            tasksToInsert.add(
                new Task(
                    Subject = 'Major gift thank-you call',
                    Priority = 'High',
                    Status = 'Not Started',
                    WhatId = opportunity.Id,
                    WhoId = opportunity.npsp__Primary_Contact__c,
                    OwnerId = opportunity.OwnerId,
                    ActivityDate = opportunity.CloseDate == null
                        ? null
                        : opportunity.CloseDate.addDays(3)
                )
            );
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }

        return dmlWrapper;
    }

    private Boolean isMajorClosedWon(Opportunity opportunity) {
        return opportunity != null &&
            opportunity.StageName == CLOSED_WON_STAGE &&
            opportunity.Amount != null &&
            opportunity.Amount >= MAJOR_GIFT_THRESHOLD;
    }
}
